using CoracaoAnimal.Client;
using CoracaoAnimal.Core;
using System.Globalization;
namespace CoracaoAnimal.App;
public sealed class MainPage:ContentPage {
 readonly ApiClient api=new(new Storage());readonly VerticalStackLayout body=new(){Spacing=12,Padding=20};readonly Label state=new(){FontSize=12,Margin=12,TextColor=Color.FromArgb("#7A6355")};readonly ScrollView scroll;bool loaded;
 public MainPage(){Title="Coração Animal";BackgroundColor=Color.FromArgb("#F7F3EE");var brand=new Grid(){BackgroundColor=Color.FromArgb("#3D2B1F"),Padding=new Thickness(18,10),ColumnDefinitions={new ColumnDefinition(64),new ColumnDefinition(GridLength.Star)}};brand.Add(new Image(){Source="brand_logo.png",HeightRequest=54,WidthRequest=54,Aspect=Aspect.AspectFit},0,0);var brandText=new VerticalStackLayout(){Spacing=0,VerticalOptions=LayoutOptions.Center};brandText.Add(new Label(){Text="CORAÇÃO ANIMAL",TextColor=Colors.White,FontAttributes=FontAttributes.Bold,FontSize=20});brandText.Add(new Label(){Text="Adoção responsável transforma vidas",TextColor=Color.FromArgb("#F5C9B0"),FontSize=12});brand.Add(brandText,1,0);var menu=new HorizontalStackLayout(){Spacing=6,Padding=10,BackgroundColor=Colors.White};foreach(var item in new(string,Func<Task>)[]{("Animais",()=>Catalog()),("Para você",()=>Catalog(true)),("Adoções",Adoptions),("Doações",Donations),("Voluntariado",Volunteer),("Conta",Profile),("Entrar",Login)})menu.Add(Button(item.Item1,item.Item2));scroll=new ScrollView(){Content=body};var grid=new Grid(){RowDefinitions={new RowDefinition(GridLength.Auto),new RowDefinition(GridLength.Auto),new RowDefinition(GridLength.Star),new RowDefinition(GridLength.Auto)}};grid.Add(brand,0,0);grid.Add(new ScrollView(){Orientation=ScrollOrientation.Horizontal,Content=menu},0,1);grid.Add(scroll,0,2);grid.Add(state,0,3);Content=grid;}
 protected override async void OnAppearing(){base.OnAppearing();if(loaded)return;loaded=true;await Run(async()=>{await api.Initialize();await Catalog();});}
 Button Button(string text,Func<Task> work){var b=new Button(){Text=text,BackgroundColor=Color.FromArgb("#4A7C59"),TextColor=Colors.White,CornerRadius=12,MinimumHeightRequest=48};b.Clicked+=async(_,_)=>{b.IsEnabled=false;await Run(work);b.IsEnabled=true;};return b;}
 async Task Run(Func<Task> work){state.Text="Carregando…";try{await work();state.Text="Atualizado";}catch(Exception ex){state.Text="Operação não concluída";await DisplayAlertAsync("Coração Animal",ex.Message,"Entendi");}}
 void Page(string title){body.Clear();body.Add(new Label(){Text=title,FontSize=28,FontAttributes=FontAttributes.Bold,TextColor=Color.FromArgb("#4A7C59")});scroll.ScrollToAsync(0,0,false);}
 void Note(string text)=>body.Add(new Label(){Text=text,TextColor=Color.FromArgb("#3D2B1F"),FontSize=16});
 Entry Field(string name,string value="",bool password=false,Keyboard? keyboard=null){Note(name);var e=new Entry(){Text=value,IsPassword=password,Keyboard=keyboard??Keyboard.Default,TextColor=Colors.Black,BackgroundColor=Colors.White,MinimumHeightRequest=48};SemanticProperties.SetDescription(e,name);body.Add(e);return e;}
 Picker Choice(string label,string[] items,string? selected=null){Note(label);var p=new Picker(){Title=label,ItemsSource=items,SelectedIndex=Math.Max(0,Array.IndexOf(items,selected)),TextColor=Colors.Black,BackgroundColor=Colors.White};body.Add(p);return p;}
 CheckBox Check(string label){var c=new CheckBox(){Color=Color.FromArgb("#4A7C59")};SemanticProperties.SetDescription(c,label);body.Add(new HorizontalStackLayout(){Children={c,new Label(){Text=label,VerticalOptions=LayoutOptions.Center,MaximumWidthRequest=280,TextColor=Colors.Black}}});return c;}
 static string Value(Picker p)=>p.SelectedItem?.ToString()??"";
 void Action(string text,Func<Task> work)=>body.Add(Button(text,work));
 Task<bool> Confirm(string text)=>DisplayAlertAsync("Confirmar",text,"Sim","Não");
 Task Settings(){Page("Conectar ao servidor");Note("Use o endereço HTTPS do site. No emulador Android, use http://10.0.2.2:5080 para acessar o servidor do computador.");var url=Field("Endereço do site",api.BaseUri?.AbsoluteUri??"",keyboard:Keyboard.Url);Action("Salvar e conectar",async()=>{await api.Configure(url.Text??"");await Catalog();});return Task.CompletedTask;}
 Task Login(){Page("Bem-vindo de volta");var email=Field("E-mail",keyboard:Keyboard.Email);var senha=Field("Senha",password:true);Action("Entrar",async()=>{await api.Login(email.Text??"",senha.Text??"");await Profile();});Action("Criar conta",Register);return Task.CompletedTask;}
 Task Register(){Page("Criar conta");var nome=Field("Nome completo");var email=Field("E-mail",keyboard:Keyboard.Email);var senha=Field("Senha (mínimo 10 caracteres)",password:true);Action("Cadastrar",async()=>{await api.Post<object>("api/auth/cadastro",new Cadastro(nome.Text??"",email.Text??"",senha.Text??""));await api.Login(email.Text??"",senha.Text??"");await Profile();});return Task.CompletedTask;}
 async Task Catalog(bool recommend=false,int page=1,string busca="",string especie="",string porte=""){if(recommend)await api.Me();var data=recommend?new Pagina<AnimalDto>(await api.Get<List<AnimalDto>>("api/me/recomendacoes")??[],0,1,12):await api.Get<Pagina<AnimalDto>>($"api/animais?pagina={page}&tamanho=12&busca={Uri.EscapeDataString(busca)}&especie={especie}&porte={porte}");Page(recommend?"Companheiros para você":"Encontre um novo amigo");if(!recommend){var search=Field("Buscar pelo nome",busca);var sp=Choice("Espécie",["","cao","gato"],especie);var size=Choice("Porte",["","pequeno","medio","grande"],porte);Action("Buscar",()=>Catalog(false,1,search.Text??"",Value(sp),Value(size)));}else Note("Afinidade baseada no seu perfil. A equipe avalia cada solicitação.");foreach(var a in data?.Itens??[]){if(a.FotoUrl!=null)body.Add(new Image(){Source=new Uri(api.BaseUri!,a.FotoUrl).AbsoluteUri,HeightRequest=190,Aspect=Aspect.AspectFit});Note($"{a.Nome} · {a.Especie} · {a.Idade} anos\n{a.Porte} · {a.Status}"+(a.Compatibilidade.HasValue?$" · Afinidade {a.Compatibilidade:0.0}%":""));Action("Conhecer "+a.Nome,()=>Details(a.Id));}if(data?.Itens.Count==0)Note("Nenhum animal cadastrado ainda. O administrador pode cadastrá-los pelo painel do site.");if(!recommend&&data!=null){if(page>1)Action("Página anterior",()=>Catalog(false,page-1,busca,especie,porte));if(page*12<data.Total)Action("Próxima página",()=>Catalog(false,page+1,busca,especie,porte));}}
 async Task Details(int id){var a=await api.Get<AnimalDto>($"api/animais/{id}")??throw new Exception("Animal não encontrado.");Page(a.Nome);if(a.FotoUrl!=null)body.Add(new Image(){Source=new Uri(api.BaseUri!,a.FotoUrl).AbsoluteUri,HeightRequest=260,Aspect=Aspect.AspectFit});Note($"{a.Especie} · {a.Raca} · {a.Idade} anos\n{a.Porte} · {a.Status}");Note(a.Descricao);if(a.Status=="disponivel"){var obs=Field("Como você pretende acolher este animal?");var terms=Check("Entendo que a solicitação será avaliada pela equipe.");Action("Solicitar adoção",async()=>{await api.Post<object>("api/me/adocoes",new AdocaoInput(id,obs.Text??"",terms.IsChecked));await Adoptions();});}}
 async Task Adoptions(){var items=await api.Get<List<AdocaoDto>>("api/me/adocoes")??[];Page("Minhas adoções");if(items.Count==0)Note("Você ainda não solicitou uma adoção.");foreach(var a in items){Note($"{a.AnimalNome} · {a.Status}\n{a.CriadoEm.ToLocalTime():d} · {a.Observacoes}");if(a.Status is "pendente" or "aprovada")Action($"Cancelar solicitação #{a.Id}",async()=>{if(await Confirm("Cancelar esta solicitação?")){await api.Post<object>($"api/me/adocoes/{a.Id}/cancelar");await Adoptions();}});}}
 async Task Donations(){var items=await api.Get<List<DoacaoDto>>("api/me/doacoes")??[];Page("Ajude o acolhimento");Note("Registro de intenção de doação. Não realiza cobrança. A equipe confirma o recebimento pelo site.");var valor=Field("Valor em reais",keyboard:Keyboard.Numeric);var forma=Choice("Forma de pagamento",["pix","transferencia","dinheiro"]);var desc=Field("Observação");var anon=Check("Não divulgar meu nome");Action("Registrar intenção",async()=>{if(!decimal.TryParse(valor.Text,NumberStyles.Number,CultureInfo.GetCultureInfo("pt-BR"),out var v))throw new Exception("Informe um valor válido.");await api.Post<object>("api/me/doacoes",new DoacaoInput(v,Value(forma),desc.Text??"",anon.IsChecked));await Donations();});foreach(var d in items){Note($"#{d.Id} · R$ {d.Valor:N2} · {d.Status}\n{d.FormaPagamento}");if(d.Status=="pendente")Action($"Cancelar doação #{d.Id}",async()=>{if(await Confirm("Cancelar esta intenção?")){await api.Post<object>($"api/me/doacoes/{d.Id}/cancelar");await Donations();}});}}
 async Task Volunteer(){var v=await api.Get<VoluntarioDto>("api/me/voluntariado");Page("Seja voluntário");Note(v==null?"Conte como você pode ajudar.":"Situação: "+v.Status);var area=Field("Área de interesse",v?.Area??"");var disp=Field("Dias e horários disponíveis",v?.Disponibilidade??"");Action("Salvar inscrição",async()=>{await api.Put<object>("api/me/voluntariado",new VoluntarioInput(area.Text??"",disp.Text??""));await Volunteer();});if(v!=null)Action("Desativar inscrição",async()=>{if(await Confirm("Desativar sua inscrição?")){await api.Delete("api/me/voluntariado");await Volunteer();}});}
 async Task Profile(){var u=await api.Me()??throw new Exception("Entre para continuar.");Page("Minha conta");Note(u.Email);var nome=Field("Nome completo",u.Nome);var cpf=Field("CPF",u.Cpf??"",keyboard:Keyboard.Numeric);var tel=Field("Telefone",u.Telefone,keyboard:Keyboard.Telephone);var end=Field("Endereço",u.Endereco);var sp=Choice("Espécie preferida",["cao","gato"],u.EspeciePreferida);var esp=Choice("Espaço disponível",["pequeno","medio","grande"],u.Espaco);var exp=Choice("Experiência",["nenhuma","alguma","muita"],u.Experiencia);Action("Salvar perfil",async()=>{await api.Put<object>("api/me/",new PerfilInput(nome.Text??"",cpf.Text,tel.Text??"",end.Text??"",Value(sp),Value(esp),Value(exp)));await Profile();});Action("Alterar senha",Password);Action("Sair",async()=>{await api.Logout();await Login();});}
 Task Password(){Page("Alterar senha");var old=Field("Senha atual",password:true);var next=Field("Nova senha (mínimo 10 caracteres)",password:true);Action("Salvar nova senha",async()=>{await api.Put<object>("api/me/senha",new SenhaInput(old.Text??"",next.Text??""));await api.Forget();await Login();});return Task.CompletedTask;}
}
